// --- Content Addressing ---

/// A BLAKE3 content hash encoded as a lowercase hex string.
///
/// Used throughout the crate to uniquely identify byte payloads by content.
/// Two values are equal iff they were produced from identical bytes.
///
/// # Examples
///
/// ```
/// use praxis::types::Blake3Hash;
///
/// let hash = Blake3Hash::content_address(b"hello world");
/// assert_eq!(hash.as_hex().len(), 64); // 32 bytes → 64 hex chars
///
/// let roundtrip = Blake3Hash::from_hex(hash.as_hex());
/// assert_eq!(hash, roundtrip);
/// ```
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct Blake3Hash(pub String);

impl Blake3Hash {
    /// Hash `bytes` with BLAKE3 and return the digest as a hex-encoded [`Blake3Hash`].
    ///
    /// This is the primary constructor for content-addressed values; use it any time
    /// you need a stable, collision-resistant identifier for a byte payload.
    ///
    /// # Examples
    ///
    /// ```
    /// use praxis::types::Blake3Hash;
    ///
    /// let h1 = Blake3Hash::content_address(b"foo");
    /// let h2 = Blake3Hash::content_address(b"foo");
    /// assert_eq!(h1, h2);
    ///
    /// let h3 = Blake3Hash::content_address(b"bar");
    /// assert_ne!(h1, h3);
    /// ```
    pub fn content_address(bytes: &[u8]) -> Self {
        Blake3Hash(blake3::hash(bytes).to_hex().to_string())
    }

    /// Construct a [`Blake3Hash`] from an existing hex string without re-hashing.
    ///
    /// No validation is performed; the caller must ensure `hex` is a valid 64-char
    /// lowercase BLAKE3 hex digest if round-trip correctness is required.
    pub fn from_hex(hex: impl Into<String>) -> Self {
        Blake3Hash(hex.into())
    }

    /// Return the hex-encoded digest as a string slice.
    pub fn as_hex(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for Blake3Hash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl From<String> for Blake3Hash {
    fn from(s: String) -> Self {
        Blake3Hash(s)
    }
}

impl From<Blake3Hash> for String {
    fn from(h: Blake3Hash) -> Self {
        h.0
    }
}

