// --- Zero-Overhead Evidence Carriage ---

/// A zero-overhead typestate wrapper that tracks the lifecycle stage of a value `T`.
///
/// The three lifecycle states — [`Raw`], [`Validated`], and [`Admitted`] — are encoded
/// as phantom type parameters so the compiler rejects out-of-order transitions at compile
/// time with no runtime cost.  `Witness` is an additional phantom marker that records
/// *which* admission policy was applied.
///
/// # Type Parameters
///
/// - `T` — the wrapped payload type.
/// - `State` — current lifecycle stage; one of [`Raw`], [`Validated`], or [`Admitted`].
/// - `Witness` — zero-sized type identifying the admitter that approved the transition.
///
/// # Examples
///
/// ```
/// use praxis::types::{Evidence, Raw};
///
/// struct MyWitness;
///
/// let ev: Evidence<u32, Raw, MyWitness> = Evidence::new(42u32);
/// assert_eq!(*ev.inner(), 42);
/// ```
pub struct Evidence<T, State: sealed::LifecycleState, Witness> {
    inner: T,
    _state: PhantomData<State>,
    _witness: PhantomData<Witness>,
}

impl<T, Witness> Evidence<T, Raw, Witness> {
    /// Wrap `inner` in the [`Raw`] lifecycle stage.
    pub fn new(inner: T) -> Self {
        Self { inner, _state: PhantomData, _witness: PhantomData }
    }

    /// Return a shared reference to the wrapped value.
    pub fn inner(&self) -> &T {
        &self.inner
    }
}

impl<T, Witness> Evidence<T, Validated, Witness> {
    /// Return a shared reference to the validated payload.
    pub fn inner(&self) -> &T {
        &self.inner
    }

    pub(crate) fn validate_unchecked(inner: T) -> Self {
        Self { inner, _state: PhantomData, _witness: PhantomData }
    }
}

impl<T, Witness> Evidence<T, Admitted, Witness> {
    /// Return a shared reference to the admitted payload.
    pub fn inner(&self) -> &T {
        &self.inner
    }

    pub(crate) fn admit_unchecked(inner: T) -> Self {
        Self { inner, _state: PhantomData, _witness: PhantomData }
    }
}

