/// A one-way gate that promotes [`Raw`] evidence to [`Admitted`] evidence.
///
/// Implementors define the admission policy for a specific payload type.  The
/// transition is one-directional: once evidence is admitted, it cannot revert
/// to [`Raw`].  The `Witness` associated type brands the output so call sites
/// can prove *which* policy admitted it.
///
/// # Examples
///
/// ```ignore
/// use praxis::types::{Admit, Evidence, Raw, Admitted};
///
/// struct AlwaysAdmit;
/// struct AlwaysAdmitWitness;
///
/// impl Admit for AlwaysAdmit {
///     type Input = u32;
///     type Witness = AlwaysAdmitWitness;
///     type Error = std::convert::Infallible;
///
///     fn admit(
///         input: Evidence<u32, Raw, AlwaysAdmitWitness>,
///     ) -> Result<Evidence<u32, Admitted, AlwaysAdmitWitness>, Self::Error> {
///         // In real code use the crate-internal admit_unchecked after performing checks.
///         todo!()
///     }
/// }
/// ```
pub trait Admit {
    /// The payload type being admitted.
    type Input;
    /// Zero-sized type that brands admitted evidence with the policy identity.
    type Witness;
    /// Error returned when admission is refused.
    type Error;

    /// Attempt to promote `input` from [`Raw`] to [`Admitted`].
    ///
    /// Returns `Ok(admitted)` on success or `Err(Self::Error)` if the policy rejects
    /// the input.
    fn admit(
        input: Evidence<Self::Input, Raw, Self::Witness>,
    ) -> Result<Evidence<Self::Input, Admitted, Self::Witness>, Self::Error>;
}

